  } catch (ClassCastException e) {
    throw new NoSuchElementException("Invalid key type for the map.");
  } catch (NullPointerException e) {
    throw new NoSuchElementException();
  }
  if (link == null) {
    return null;
  } else {
    return link.getItem();
  }
